#include <stdio.h>
#include <time.h>

int main(void)
{
    time_t now = time(NULL);
    struct tm local_copy;
    struct tm utc_copy;
    struct tm *parts;
    char local_text[64];
    char utc_text[64];

    if (now == (time_t)-1) {
        fputs("Current time is unavailable.\n", stderr);
        return 1;
    }

    parts = localtime(&now);
    if (parts == NULL) {
        fputs("Local-time conversion failed.\n", stderr);
        return 1;
    }
    local_copy = *parts;

    parts = gmtime(&now);
    if (parts == NULL) {
        fputs("UTC conversion failed.\n", stderr);
        return 1;
    }
    utc_copy = *parts;

    if (strftime(local_text, sizeof local_text,
                 "%Y-%m-%d %H:%M:%S", &local_copy) == 0U) {
        fputs("Local-time formatting failed.\n", stderr);
        return 1;
    }
    if (strftime(utc_text, sizeof utc_text,
                 "%Y-%m-%d %H:%M:%S", &utc_copy) == 0U) {
        fputs("UTC formatting failed.\n", stderr);
        return 1;
    }

    printf("Local: %s\nUTC:   %s\n", local_text, utc_text);
    return 0;
}

#include <stdio.h>
#include <time.h>

int main(void)
{
    struct tm start_parts = {0};
    struct tm end_parts = {0};
    time_t start_time;
    time_t end_time;
    double elapsed;
    char start_text[64];
    char end_text[64];

    start_parts.tm_year = 2025 - 1900;
    start_parts.tm_mon = 0;
    start_parts.tm_mday = 15;
    start_parts.tm_hour = 12;
    start_parts.tm_isdst = -1;

    end_parts = start_parts;
    end_parts.tm_mday = 16;

    start_time = mktime(&start_parts);
    end_time = mktime(&end_parts);
    if (start_time == (time_t)-1 || end_time == (time_t)-1) {
        fputs("Calendar-time conversion failed.\n", stderr);
        return 1;
    }

    elapsed = difftime(end_time, start_time);
    if (strftime(start_text, sizeof start_text,
                 "%Y-%m-%d %H:%M:%S", &start_parts) == 0U ||
        strftime(end_text, sizeof end_text,
                 "%Y-%m-%d %H:%M:%S", &end_parts) == 0U) {
        fputs("Date formatting failed.\n", stderr);
        return 1;
    }

    printf("Start local time: %s\n", start_text);
    printf("End local time:   %s\n", end_text);
    printf("Elapsed seconds:  %.0f\n", elapsed);
    return 0;
}
